{
  "name": "LiftLog",
  "description": "A visually clean workout tracker focusing on progressive overload. Track sets, reps, and visualize your strength gains."
}

export interface Exercise {
  id: string;
  name: string;
  category: 'Push' | 'Pull' | 'Legs' | 'Core' | 'Other';
}

export interface WorkoutSet {
  id: string;
  weight: number;
  reps: number;
  completed: boolean;
}

export interface WorkoutSession {
  id: string;
  date: string; // ISO Date String YYYY-MM-DD
  exerciseId: string;
  sets: WorkoutSet[];
}

// Helper type for the graph data
export interface ProgressDataPoint {
  date: string;
  maxWeight: number;
  volume: number;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { Plus, Trash2, CheckCircle2, Circle } from 'lucide-react';
import { Exercise, WorkoutSession, WorkoutSet } from '../types';

interface TrackerViewProps {
  currentDate: string;
  exercises: Exercise[];
  sessions: WorkoutSession[];
  onAddSession: (exerciseId: string) => void;
  onUpdateSet: (sessionId: string, sets: WorkoutSet[]) => void;
  onDeleteSession: (sessionId: string) => void;
  onAddExercise: (name: string) => void;
}

export const TrackerView: React.FC<TrackerViewProps> = ({
  currentDate,
  exercises,
  sessions,
  onAddSession,
  onUpdateSet,
  onDeleteSession,
  onAddExercise
}) => {
  const [isAddingExercise, setIsAddingExercise] = useState(false);
  const [selectedExerciseId, setSelectedExerciseId] = useState<string>('');
  const [newExerciseName, setNewExerciseName] = useState('');

  // Filter sessions for today
  const todaysSessions = sessions.filter(s => s.date === currentDate);

  const handleAddSet = (session: WorkoutSession) => {
    const newSet: WorkoutSet = {
      id: Date.now().toString() + Math.random(),
      weight: session.sets.length > 0 ? session.sets[session.sets.length - 1].weight : 0,
      reps: session.sets.length > 0 ? session.sets[session.sets.length - 1].reps : 0,
      completed: false,
    };
    onUpdateSet(session.id, [...session.sets, newSet]);
  };

  const handleUpdateSetData = (session: WorkoutSession, setId: string, field: 'weight' | 'reps', value: number) => {
    const updatedSets = session.sets.map(set => 
      set.id === setId ? { ...set, [field]: value } : set
    );
    onUpdateSet(session.id, updatedSets);
  };

  const toggleSetComplete = (session: WorkoutSession, setId: string) => {
    const updatedSets = session.sets.map(set => 
      set.id === setId ? { ...set, completed: !set.completed } : set
    );
    onUpdateSet(session.id, updatedSets);
  };

  const removeSet = (session: WorkoutSession, setId: string) => {
    const updatedSets = session.sets.filter(set => set.id !== setId);
    onUpdateSet(session.id, updatedSets);
  };

  const handleCreateExercise = () => {
    if (newExerciseName.trim()) {
      onAddExercise(newExerciseName);
      setNewExerciseName('');
      setIsAddingExercise(false);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Today's Log Card */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100 min-h-[400px]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-slate-400 font-bold text-sm tracking-wider uppercase">Today's Workout</h2>
          <span className="text-xs font-medium px-3 py-1 bg-slate-100 text-slate-500 rounded-full">
            {todaysSessions.length} Exercises
          </span>
        </div>

        {todaysSessions.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-center space-y-4">
            <div className="w-16 h-16 bg-primary-50 rounded-full flex items-center justify-center text-primary-400">
              <Plus size={32} />
            </div>
            <p className="text-slate-400">No magic added for this date yet ✨</p>
          </div>
        ) : (
          <div className="space-y-8">
            {todaysSessions.map(session => {
              const exercise = exercises.find(e => e.id === session.exerciseId);
              return (
                <div key={session.id} className="animate-fade-in">
                  <div className="flex justify-between items-center mb-3">
                    <h3 className="text-lg font-bold text-slate-800">{exercise?.name}</h3>
                    <button 
                      onClick={() => onDeleteSession(session.id)}
                      className="text-slate-300 hover:text-red-400 transition-colors"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>

                  <div className="space-y-2">
                    {/* Header Row */}
                    <div className="grid grid-cols-10 gap-2 text-xs font-semibold text-slate-400 mb-2 px-2">
                      <div className="col-span-1 text-center">#</div>
                      <div className="col-span-3 text-center">KG</div>
                      <div className="col-span-3 text-center">REPS</div>
                      <div className="col-span-3 text-center">DONE</div>
                    </div>

                    {session.sets.map((set, idx) => (
                      <div key={set.id} className={`grid grid-cols-10 gap-2 items-center p-2 rounded-xl transition-all ${set.completed ? 'bg-green-50/50' : 'bg-slate-50'}`}>
                        <div className="col-span-1 text-center font-bold text-slate-400">{idx + 1}</div>
                        <div className="col-span-3">
                          <input 
                            type="number" 
                            value={set.weight || ''} 
                            onChange={(e) => handleUpdateSetData(session, set.id, 'weight', Number(e.target.value))}
                            className="w-full text-center bg-white rounded-lg py-1 text-slate-800 font-semibold focus:ring-2 focus:ring-primary-200 outline-none"
                            placeholder="0"
                          />
                        </div>
                        <div className="col-span-3">
                          <input 
                            type="number" 
                            value={set.reps || ''} 
                            onChange={(e) => handleUpdateSetData(session, set.id, 'reps', Number(e.target.value))}
                            className="w-full text-center bg-white rounded-lg py-1 text-slate-800 font-semibold focus:ring-2 focus:ring-primary-200 outline-none"
                            placeholder="0"
                          />
                        </div>
                        <div className="col-span-3 flex justify-center items-center gap-2">
                          <button onClick={() => toggleSetComplete(session, set.id)}>
                            {set.completed ? (
                              <CheckCircle2 className="text-green-500 fill-green-100" size={24} />
                            ) : (
                              <Circle className="text-slate-300" size={24} />
                            )}
                          </button>
                          {/* Only show delete on long press or similar? Keeping it simple for now, maybe just double click to delete or small x */}
                        </div>
                      </div>
                    ))}
                  </div>

                  <button 
                    onClick={() => handleAddSet(session)}
                    className="w-full mt-3 py-2 text-sm font-semibold text-primary-600 bg-primary-50 rounded-xl hover:bg-primary-100 transition-colors flex items-center justify-center gap-2"
                  >
                    <Plus size={16} /> Add Set
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Add Exercise Section */}
        <div className="mt-8 pt-6 border-t border-slate-100">
           {!isAddingExercise ? (
             <div className="flex gap-2">
                <select 
                  className="flex-1 bg-slate-50 text-slate-600 py-3 px-4 rounded-xl outline-none border border-transparent focus:border-primary-300 transition-all appearance-none cursor-pointer"
                  value={selectedExerciseId}
                  onChange={(e) => setSelectedExerciseId(e.target.value)}
                >
                  <option value="" disabled>Select an exercise...</option>
                  {exercises.map(ex => (
                    <option key={ex.id} value={ex.id}>{ex.name}</option>
                  ))}
                </select>
                <button 
                  disabled={!selectedExerciseId}
                  onClick={() => {
                    if (selectedExerciseId) {
                      onAddSession(selectedExerciseId);
                      setSelectedExerciseId('');
                    }
                  }}
                  className="bg-slate-900 text-white rounded-xl w-14 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors shadow-lg shadow-slate-200"
                >
                  <Plus size={24} />
                </button>
             </div>
           ) : (
             <div className="flex gap-2">
               <input 
                 autoFocus
                 type="text" 
                 placeholder="New exercise name..."
                 className="flex-1 bg-white border border-slate-200 text-slate-800 py-3 px-4 rounded-xl outline-none focus:ring-2 focus:ring-primary-200"
                 value={newExerciseName}
                 onChange={(e) => setNewExerciseName(e.target.value)}
               />
               <button 
                 onClick={handleCreateExercise}
                 className="bg-primary-600 text-white rounded-xl px-4 font-semibold text-sm"
               >
                 Save
               </button>
               <button 
                 onClick={() => setIsAddingExercise(false)}
                 className="text-slate-400 px-2"
               >
                 Cancel
               </button>
             </div>
           )}

           {!isAddingExercise && (
             <button 
               onClick={() => setIsAddingExercise(true)}
               className="mt-3 text-xs font-semibold text-primary-500 hover:text-primary-600 block mx-auto"
             >
               + Create new exercise
             </button>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Exercise, WorkoutSession } from '../types';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Area,
  AreaChart
} from 'recharts';

interface ProgressViewProps {
  exercises: Exercise[];
  sessions: WorkoutSession[];
}

export const ProgressView: React.FC<ProgressViewProps> = ({ exercises, sessions }) => {
  // Default to the first exercise if available
  const [selectedExerciseId, setSelectedExerciseId] = useState<string>(exercises[0]?.id || '');

  const stats = useMemo(() => {
    if (!selectedExerciseId) return [];

    // Filter sessions for this exercise
    const relevantSessions = sessions
      .filter(s => s.exerciseId === selectedExerciseId)
      // Sort by date ascending
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Map to graph data format
    return relevantSessions.map(session => {
      // Calculate max weight lifted in this session
      const maxWeight = Math.max(...session.sets.map(s => s.weight || 0), 0);
      // Calculate total volume (sets * reps * weight)
      const volume = session.sets.reduce((acc, s) => acc + (s.weight * s.reps), 0);

      // Format date for display (e.g., "Jan 5")
      const dateObj = new Date(session.date);
      const dateStr = dateObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

      return {
        date: dateStr,
        maxWeight,
        volume
      };
    });
  }, [selectedExerciseId, sessions]);

  // Calculate improvement percentage
  const improvement = useMemo(() => {
    if (stats.length < 2) return 0;
    const first = stats[0].maxWeight;
    const last = stats[stats.length - 1].maxWeight;
    if (first === 0) return 0;
    return Math.round(((last - first) / first) * 100);
  }, [stats]);

  return (
    <div className="space-y-6 pb-24">
      {/* Control Card */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100">
        <label className="text-xs font-bold text-slate-400 tracking-wider uppercase mb-2 block">
          Select Exercise
        </label>
        <select
          value={selectedExerciseId}
          onChange={(e) => setSelectedExerciseId(e.target.value)}
          className="w-full bg-slate-50 text-slate-800 font-bold text-lg py-3 px-4 rounded-xl outline-none focus:ring-2 focus:ring-primary-100 transition-all appearance-none"
        >
          {exercises.map(ex => (
            <option key={ex.id} value={ex.id}>{ex.name}</option>
          ))}
        </select>

        {stats.length > 0 && (
          <div className="mt-6 flex items-center justify-between">
            <div>
              <p className="text-sm text-slate-400">Current Max</p>
              <p className="text-3xl font-black text-slate-800">
                {stats[stats.length - 1].maxWeight} <span className="text-sm font-normal text-slate-400">kg</span>
              </p>
            </div>
            <div className={`text-right ${improvement >= 0 ? 'text-green-500' : 'text-red-500'}`}>
              <p className="text-sm font-medium opacity-60">Since Start</p>
              <p className="text-xl font-bold">
                {improvement > 0 ? '+' : ''}{improvement}%
              </p>
            </div>
          </div>
        )}
      </div>

      {/* Graph Card */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100 min-h-[350px]">
        <h3 className="text-slate-800 font-bold text-lg mb-6">Performance Trend</h3>

        {stats.length < 2 ? (
          <div className="h-64 flex flex-col items-center justify-center text-center text-slate-400 p-4">
            <p>Not enough data yet.</p>
            <p className="text-sm mt-2">Log at least 2 workouts for this exercise to see your progress graph.</p>
          </div>
        ) : (
          <div className="h-64 w-full -ml-4">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={stats}>
                <defs>
                  <linearGradient id="colorWeight" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  axisLine={false}
                  tickLine={false}
                  tick={{ fill: '#94a3b8', fontSize: 12 }}
                  dy={10}
                />
                <YAxis 
                  axisLine={false}
                  tickLine={false}
                  tick={{ fill: '#94a3b8', fontSize: 12 }}
                  domain={['dataMin - 5', 'dataMax + 5']}
                />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Area 
                  type="monotone" 
                  dataKey="maxWeight" 
                  stroke="#8b5cf6" 
                  strokeWidth={3}
                  fillOpacity={1} 
                  fill="url(#colorWeight)" 
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Settings, ChevronLeft, ChevronRight, Dumbbell, LineChart } from 'lucide-react';
import { INITIAL_EXERCISES } from './constants';
import { Exercise, WorkoutSession, WorkoutSet } from './types';
import { TrackerView } from './components/TrackerView';
import { ProgressView } from './components/ProgressView';

export default function App() {
  // --- State ---
  const [exercises, setExercises] = useState<Exercise[]>(() => {
    const saved = localStorage.getItem('liftlog_exercises');
    return saved ? JSON.parse(saved) : INITIAL_EXERCISES;
  });

  const [sessions, setSessions] = useState<WorkoutSession[]>(() => {
    const saved = localStorage.getItem('liftlog_sessions');
    return saved ? JSON.parse(saved) : [];
  });

  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState<'tracker' | 'progress'>('tracker');

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('liftlog_exercises', JSON.stringify(exercises));
  }, [exercises]);

  useEffect(() => {
    localStorage.setItem('liftlog_sessions', JSON.stringify(sessions));
  }, [sessions]);

  // --- Helpers ---
  const formattedDateString = currentDate.toISOString().split('T')[0];

  const displayDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { weekday: 'long', month: 'long', day: 'numeric' };
    return currentDate.toLocaleDateString('en-US', options);
  }, [currentDate]);

  const changeDate = (days: number) => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() + days);
    setCurrentDate(newDate);
  };

  // --- Weekly Stats Logic for the "Purple Pill" ---
  const weeklyStats = useMemo(() => {
    // Get start of week (Sunday)
    const startOfWeek = new Date(currentDate);
    startOfWeek.setDate(currentDate.getDate() - currentDate.getDay());
    startOfWeek.setHours(0,0,0,0);

    // Get end of week
    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23,59,59,999);

    const weekSessions = sessions.filter(s => {
      const d = new Date(s.date);
      return d >= startOfWeek && d <= endOfWeek;
    });

    let totalVolume = 0;
    let setsCompleted = 0;

    weekSessions.forEach(session => {
      session.sets.forEach(set => {
        if (set.completed) {
          setsCompleted++;
          totalVolume += (set.weight * set.reps);
        }
      });
    });

    return { volume: totalVolume, sets: setsCompleted };
  }, [sessions, currentDate]);


  // --- Handlers ---
  const handleAddSession = (exerciseId: string) => {
    const newSession: WorkoutSession = {
      id: Date.now().toString(),
      date: formattedDateString,
      exerciseId,
      sets: [
        { id: Date.now().toString() + '1', weight: 0, reps: 0, completed: false }
      ]
    };
    setSessions([...sessions, newSession]);
  };

  const handleUpdateSet = (sessionId: string, updatedSets: WorkoutSet[]) => {
    setSessions(prev => prev.map(s => 
      s.id === sessionId ? { ...s, sets: updatedSets } : s
    ));
  };

  const handleDeleteSession = (sessionId: string) => {
    setSessions(prev => prev.filter(s => s.id !== sessionId));
  };

  const handleAddExercise = (name: string) => {
    const newEx: Exercise = {
      id: Date.now().toString(),
      name,
      category: 'Other'
    };
    setExercises([...exercises, newEx]);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-800 font-sans selection:bg-primary-200">

      {/* --- Header Section --- */}
      <div className="px-6 pt-12 pb-6">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-900">
              Hey! Athlete <span className="animate-pulse inline-block">💪</span>
            </h1>
          </div>
          <button className="p-3 bg-white rounded-2xl shadow-sm text-slate-600 hover:bg-slate-50 transition-colors">
            <Settings size={20} />
          </button>
        </div>

        {/* Date Navigator */}
        <div className="flex items-center gap-2 text-slate-500 mb-8">
          <button onClick={() => changeDate(-1)} className="p-1 hover:text-primary-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <span className="font-semibold text-sm">{displayDate}</span>
          <button onClick={() => changeDate(1)} className="p-1 hover:text-primary-600 transition-colors">
            <ChevronRight size={20} />
          </button>
        </div>

        {/* --- Stats Pill (Weekly Average Style) --- */}
        <div className="bg-white rounded-[2.5rem] p-1 shadow-sm mb-6 flex items-center justify-between relative overflow-hidden">
           {/* Decorative Gradient Blob */}
           <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-violet-500 via-fuchsia-500 to-primary-500 opacity-20"></div>

           <div className="flex-1 p-5 text-center border-r border-slate-100">
             <div className="bg-gradient-to-r from-violet-600 to-fuchsia-600 text-white text-[10px] font-bold px-3 py-1 rounded-full inline-block mb-2 shadow-md shadow-violet-200">
               WEEKLY VOLUME
             </div>
             <p className="text-3xl font-black text-slate-800">
               {(weeklyStats.volume / 1000).toFixed(1)}<span className="text-base font-medium text-slate-400">k</span>
             </p>
             <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-1">KG Lifted</p>
           </div>

           <div className="flex-1 p-5 text-center">
              <p className="text-3xl font-black text-slate-800">
               {weeklyStats.sets}
             </p>
             <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-1">Sets Completed</p>
           </div>
        </div>

        {/* --- Main Content Area --- */}
        {activeTab === 'tracker' ? (
          <TrackerView 
            currentDate={formattedDateString}
            exercises={exercises}
            sessions={sessions}
            onAddSession={handleAddSession}
            onUpdateSet={handleUpdateSet}
            onDeleteSession={handleDeleteSession}
            onAddExercise={handleAddExercise}
          />
        ) : (
          <ProgressView 
            exercises={exercises}
            sessions={sessions}
          />
        )}
      </div>

      {/* --- Bottom Navigation --- */}
      <div className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-md border-t border-slate-100 p-4 pb-8 flex justify-around items-center z-50">
        <button 
          onClick={() => setActiveTab('tracker')}
          className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'tracker' ? 'text-primary-600 scale-105' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <div className={`p-2 rounded-2xl ${activeTab === 'tracker' ? 'bg-primary-50' : 'bg-transparent'}`}>
            <Dumbbell size={24} fill={activeTab === 'tracker' ? "currentColor" : "none"} />
          </div>
          <span className="text-[10px] font-bold tracking-wide">Tracker</span>
        </button>

        <button 
          onClick={() => setActiveTab('progress')}
          className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'progress' ? 'text-primary-600 scale-105' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <div className={`p-2 rounded-2xl ${activeTab === 'progress' ? 'bg-primary-50' : 'bg-transparent'}`}>
             <LineChart size={24} />
          </div>
          <span className="text-[10px] font-bold tracking-wide">Progress</span>
        </button>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { Settings, ChevronLeft, ChevronRight, Dumbbell, LineChart, Calendar as CalendarIcon, X } from 'lucide-react';
import { INITIAL_EXERCISES } from './constants';
import { Exercise, WorkoutSession, WorkoutSet } from './types';
import { TrackerView } from './components/TrackerView';
import { ProgressView } from './components/ProgressView';
import { Calendar } from './components/Calendar';

