  // --- State ---
  const [exercises, setExercises] = useState<Exercise[]>(() => {
    const saved = localStorage.getItem('liftlog_exercises');
    return saved ? JSON.parse(saved) : INITIAL_EXERCISES;
  });

  const [sessions, setSessions] = useState<WorkoutSession[]>(() => {
    const saved = localStorage.getItem('liftlog_sessions');
    return saved ? JSON.parse(saved) : [];
  });

  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeTab, setActiveTab] = useState<'tracker' | 'progress'>('tracker');
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('liftlog_exercises', JSON.stringify(exercises));
  }, [exercises]);

  useEffect(() => {
    localStorage.setItem('liftlog_sessions', JSON.stringify(sessions));
  }, [sessions]);

  // --- Helpers ---
  const formattedDateString = currentDate.toISOString().split('T')[0];

  const displayDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { weekday: 'long', month: 'long', day: 'numeric' };
    return currentDate.toLocaleDateString('en-US', options);
  }, [currentDate]);

  const changeDate = (days: number) => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() + days);
    setCurrentDate(newDate);
  };

  // --- Weekly Stats Logic (Updated: Counts all logged sets) ---
  const weeklyStats = useMemo(() => {
    // Get start of week (Monday)
    const d = new Date(currentDate);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    const startOfWeek = new Date(d.setDate(diff));
    startOfWeek.setHours(0,0,0,0);

    // Get end of week
    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23,59,59,999);

    const weekSessions = sessions.filter(s => {
      const sDate = new Date(s.date);
      return sDate >= startOfWeek && sDate <= endOfWeek;
    });

    let totalVolume = 0;
    let setsCompleted = 0;

    weekSessions.forEach(session => {
      session.sets.forEach(set => {
        // Count all sets that have data
        setsCompleted++;
        totalVolume += (set.weight * set.reps);
      });
    });

    return { volume: totalVolume, sets: setsCompleted };
  }, [sessions, currentDate]);


  // --- Handlers ---
  const handleAddSession = (exerciseId: string) => {
    const newSession: WorkoutSession = {
      id: Date.now().toString(),
      date: formattedDateString,
      exerciseId,
      sets: [
        { id: Date.now().toString() + '1', weight: 0, reps: 0, completed: true }
      ]
    };
    setSessions([...sessions, newSession]);
  };

  const handleUpdateSet = (sessionId: string, updatedSets: WorkoutSet[]) => {
    setSessions(prev => prev.map(s => 
      s.id === sessionId ? { ...s, sets: updatedSets } : s
    ));
  };

  const handleDeleteSession = (sessionId: string) => {
    setSessions(prev => prev.filter(s => s.id !== sessionId));
  };

  const handleAddExercise = (name: string) => {
    const newEx: Exercise = {
      id: Date.now().toString(),
      name,
      category: 'Other'
    };
    setExercises([...exercises, newEx]);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-800 font-sans selection:bg-primary-200">

      {/* --- Header Section --- */}
      <div className="px-6 pt-12 pb-6">
