            <button onClick={() => changeDate(-1)} className="p-2 bg-white rounded-xl shadow-sm hover:text-primary-600 transition-colors">
              <ChevronLeft size={20} />
            </button>
            <button 
              onClick={() => setIsCalendarOpen(true)}
              className="flex items-center gap-2 px-4 py-2 bg-white rounded-xl shadow-sm font-semibold text-sm hover:text-primary-600 transition-colors"
            >
              <CalendarIcon size={16} />
              {displayDate}
            </button>
            <button onClick={() => changeDate(1)} className="p-2 bg-white rounded-xl shadow-sm hover:text-primary-600 transition-colors">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        {/* --- Stats Pill --- */}
        <div className="bg-white rounded-[2.5rem] p-1 shadow-sm mb-6 flex items-center justify-between relative overflow-hidden">
           {/* Decorative Gradient Blob */}
           <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-violet-500 via-fuchsia-500 to-primary-500 opacity-20"></div>

           <div className="flex-1 p-5 text-center border-r border-slate-100">
             <div className="bg-gradient-to-r from-violet-600 to-fuchsia-600 text-white text-[10px] font-bold px-3 py-1 rounded-full inline-block mb-2 shadow-md shadow-violet-200">
               WEEKLY VOLUME
             </div>
             <p className="text-3xl font-black text-slate-800">
               {(weeklyStats.volume / 1000).toFixed(1)}<span className="text-base font-medium text-slate-400">k</span>
             </p>
             <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-1">KG Lifted</p>
           </div>

           <div className="flex-1 p-5 text-center">
              <p className="text-3xl font-black text-slate-800">
               {weeklyStats.sets}
             </p>
             <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-1">Sets Completed</p>
           </div>
        </div>

        {/* --- Main Content Area --- */}
        {activeTab === 'tracker' ? (
          <TrackerView 
            currentDate={formattedDateString}
            exercises={exercises}
