import React, { useState, useMemo } from 'react';
import { Plus, Trash2, X, History } from 'lucide-react';
import { Exercise, WorkoutSession, WorkoutSet } from '../types';

interface TrackerViewProps {
  currentDate: string;
  exercises: Exercise[];
  sessions: WorkoutSession[];
  onAddSession: (exerciseId: string) => void;
  onUpdateSet: (sessionId: string, sets: WorkoutSet[]) => void;
  onDeleteSession: (sessionId: string) => void;
  onAddExercise: (name: string) => void;
}

export const TrackerView: React.FC<TrackerViewProps> = ({
  currentDate,
  exercises,
  sessions,
  onAddSession,
  onUpdateSet,
  onDeleteSession,
  onAddExercise
}) => {
  const [isAddingExercise, setIsAddingExercise] = useState(false);
  const [selectedExerciseId, setSelectedExerciseId] = useState<string>('');
  const [newExerciseName, setNewExerciseName] = useState('');

  // Filter sessions for today
  const todaysSessions = sessions.filter(s => s.date === currentDate);

  // Sort exercises by most used
  const sortedExercises = useMemo(() => {
    // Create a map of exercise usage counts
    const counts: Record<string, number> = {};
    sessions.forEach(s => {
      counts[s.exerciseId] = (counts[s.exerciseId] || 0) + 1;
    });

    // Sort exercises based on count (descending)
    return [...exercises].sort((a, b) => {
      const countA = counts[a.id] || 0;
      const countB = counts[b.id] || 0;
      return countB - countA;
    });
  }, [exercises, sessions]);

  // Helper to get previous session details
  const getPreviousSessionSummary = (exerciseId: string) => {
    // Find all sessions for this exercise BEFORE the current date
    const prevSessions = sessions.filter(s => 
      s.exerciseId === exerciseId && 
      new Date(s.date) < new Date(currentDate)
    );

    // Sort by date descending (newest first)
    prevSessions.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const lastSession = prevSessions[0];
    if (!lastSession || lastSession.sets.length === 0) return null;

    // Create a summary string: e.g., "60kg × 8, 60kg × 8"
    const setStrings = lastSession.sets.map(set => `${set.weight}kg × ${set.reps}`);
    // Truncate if too long (e.g., first 3 sets)
    const displayString = setStrings.slice(0, 3).join(', ') + (setStrings.length > 3 ? '...' : '');

    return displayString;
  };

  const handleAddSet = (session: WorkoutSession) => {
    const newSet: WorkoutSet = {
      id: Date.now().toString() + Math.random(),
      weight: session.sets.length > 0 ? session.sets[session.sets.length - 1].weight : 0,
      reps: session.sets.length > 0 ? session.sets[session.sets.length - 1].reps : 0,
      completed: true,
    };
    onUpdateSet(session.id, [...session.sets, newSet]);
  };

  const handleUpdateSetData = (session: WorkoutSession, setId: string, field: 'weight' | 'reps', value: number) => {
    const updatedSets = session.sets.map(set => 
      set.id === setId ? { ...set, [field]: value } : set
    );
    onUpdateSet(session.id, updatedSets);
  };

  const removeSet = (session: WorkoutSession, setId: string) => {
    const updatedSets = session.sets.filter(set => set.id !== setId);
    onUpdateSet(session.id, updatedSets);
  };

  const handleCreateExercise = () => {
    if (newExerciseName.trim()) {
      onAddExercise(newExerciseName);
      setNewExerciseName('');
      setIsAddingExercise(false);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Today's Log Card */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100 min-h-[400px]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-slate-400 font-bold text-sm tracking-wider uppercase">Today's Workout</h2>
          <span className="text-xs font-medium px-3 py-1 bg-slate-100 text-slate-500 rounded-full">
            {todaysSessions.length} Exercises
          </span>
        </div>

        {todaysSessions.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-center space-y-4">
            <div className="w-16 h-16 bg-primary-50 rounded-full flex items-center justify-center text-primary-400">
              <Plus size={32} />
            </div>
            <p className="text-slate-400">No magic added for this date yet ✨</p>
          </div>
        ) : (
          <div className="space-y-8">
            {todaysSessions.map(session => {
              const exercise = exercises.find(e => e.id === session.exerciseId);
              const prevSummary = getPreviousSessionSummary(session.exerciseId);

              return (
                <div key={session.id} className="animate-fade-in">
                  <div className="flex justify-between items-start mb-3">
                    <div>
                      <h3 className="text-lg font-bold text-slate-800">{exercise?.name}</h3>
                      {prevSummary && (
                        <div className="flex items-center gap-1.5 mt-1 text-xs text-slate-400 font-medium">
                          <History size={12} className="opacity-70" />
                          <span>Last: {prevSummary}</span>
                        </div>
                      )}
                    </div>
                    <button 
                      onClick={() => onDeleteSession(session.id)}
                      className="text-slate-300 hover:text-red-400 transition-colors pt-1"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>

                  <div className="space-y-2">
                    {/* Header Row */}
                    <div className="grid grid-cols-12 gap-2 text-xs font-semibold text-slate-400 mb-2 px-2">
                      <div className="col-span-2 text-center">SET</div>
                      <div className="col-span-4 text-center">KG</div>
                      <div className="col-span-4 text-center">REPS</div>
                      <div className="col-span-2 text-center"></div>
                    </div>

                    {session.sets.map((set, idx) => (
                      <div key={set.id} className="grid grid-cols-12 gap-2 items-center p-2 rounded-xl bg-slate-50 transition-all hover:bg-slate-100">
                        <div className="col-span-2 text-center font-bold text-slate-400">{idx + 1}</div>
                        <div className="col-span-4">
                          <input 
                            type="number" 
                            value={set.weight || ''} 
                            onChange={(e) => handleUpdateSetData(session, set.id, 'weight', Number(e.target.value))}
                            className="w-full text-center bg-white rounded-lg py-2 text-slate-800 font-bold text-lg focus:ring-2 focus:ring-primary-200 outline-none shadow-sm"
                            placeholder="0"
                          />
                        </div>
                        <div className="col-span-4">
                          <input 
                            type="number" 
                            value={set.reps || ''} 
                            onChange={(e) => handleUpdateSetData(session, set.id, 'reps', Number(e.target.value))}
                            className="w-full text-center bg-white rounded-lg py-2 text-slate-800 font-bold text-lg focus:ring-2 focus:ring-primary-200 outline-none shadow-sm"
                            placeholder="0"
                          />
                        </div>
                        <div className="col-span-2 flex justify-center">
                           <button 
                            onClick={() => removeSet(session, set.id)}
                            className="p-2 text-slate-300 hover:text-red-400 transition-colors"
                           >
                             <X size={16} />
                           </button>
                        </div>
                      </div>
                    ))}
                  </div>

                  <button 
                    onClick={() => handleAddSet(session)}
                    className="w-full mt-3 py-2 text-sm font-semibold text-primary-600 bg-primary-50 rounded-xl hover:bg-primary-100 transition-colors flex items-center justify-center gap-2"
                  >
                    <Plus size={16} /> Add Set
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Add Exercise Section */}
        <div className="mt-8 pt-6 border-t border-slate-100">
           {!isAddingExercise ? (
             <div className="flex gap-2">
                <select 
                  className="flex-1 bg-slate-50 text-slate-600 py-3 px-4 rounded-xl outline-none border border-transparent focus:border-primary-300 transition-all appearance-none cursor-pointer"
                  value={selectedExerciseId}
                  onChange={(e) => setSelectedExerciseId(e.target.value)}
                >
                  <option value="" disabled>Select an exercise...</option>
                  {sortedExercises.map(ex => (
                    <option key={ex.id} value={ex.id}>{ex.name}</option>
                  ))}
                </select>
                <button 
                  disabled={!selectedExerciseId}
                  onClick={() => {
                    if (selectedExerciseId) {
                      onAddSession(selectedExerciseId);
                      setSelectedExerciseId('');
                    }
                  }}
                  className="bg-slate-900 text-white rounded-xl w-14 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors shadow-lg shadow-slate-200"
                >
                  <Plus size={24} />
                </button>
             </div>
           ) : (
             <div className="flex gap-2">
               <input 
                 autoFocus
                 type="text" 
                 placeholder="New exercise name..."
                 className="flex-1 bg-white border border-slate-200 text-slate-800 py-3 px-4 rounded-xl outline-none focus:ring-2 focus:ring-primary-200"
                 value={newExerciseName}
                 onChange={(e) => setNewExerciseName(e.target.value)}
               />
               <button 
                 onClick={handleCreateExercise}
                 className="bg-primary-600 text-white rounded-xl px-4 font-semibold text-sm"
               >
                 Save
               </button>
               <button 
                 onClick={() => setIsAddingExercise(false)}
                 className="text-slate-400 px-2"
               >
                 Cancel
               </button>
             </div>
           )}

           {!isAddingExercise && (
             <button 
               onClick={() => setIsAddingExercise(true)}
               className="mt-3 text-xs font-semibold text-primary-500 hover:text-primary-600 block mx-auto"
             >
               + Create new exercise
             </button>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Plus, Trash2, X, History } from 'lucide-react';
import { Exercise, WorkoutSession, WorkoutSet } from '../types';

interface TrackerViewProps {
  currentDate: string;
  exercises: Exercise[];
  sessions: WorkoutSession[];
  onAddSession: (exerciseId: string) => void;
  onUpdateSet: (sessionId: string, sets: WorkoutSet[]) => void;
  onDeleteSession: (sessionId: string) => void;
  onAddExercise: (name: string) => void;
}

export const TrackerView: React.FC<TrackerViewProps> = ({
  currentDate,
  exercises,
  sessions,
  onAddSession,
  onUpdateSet,
  onDeleteSession,
  onAddExercise
}) => {
  const [isAddingExercise, setIsAddingExercise] = useState(false);
  const [selectedExerciseId, setSelectedExerciseId] = useState<string>('');
  const [newExerciseName, setNewExerciseName] = useState('');

  // Filter sessions for today
  const todaysSessions = sessions.filter(s => s.date === currentDate);

  // Sort exercises by most used
  const sortedExercises = useMemo(() => {
    // Create a map of exercise usage counts
    const counts: Record<string, number> = {};
    sessions.forEach(s => {
      counts[s.exerciseId] = (counts[s.exerciseId] || 0) + 1;
    });

    // Sort exercises based on count (descending)
    return [...exercises].sort((a, b) => {
      const countA = counts[a.id] || 0;
      const countB = counts[b.id] || 0;
      return countB - countA;
    });
  }, [exercises, sessions]);

  // Helper to find the last session
  const getLastSession = (exerciseId: string) => {
    const prevSessions = sessions.filter(s => 
      s.exerciseId === exerciseId && 
      new Date(s.date) < new Date(currentDate)
    );
    prevSessions.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    return prevSessions[0];
  };

  // Helper to get previous session details text
  const getPreviousSessionSummary = (exerciseId: string) => {
    const lastSession = getLastSession(exerciseId);
    if (!lastSession || lastSession.sets.length === 0) return null;

    // Create a summary string: e.g., "60kg × 8, 60kg × 8"
    const setStrings = lastSession.sets.map(set => `${set.weight}kg × ${set.reps}`);
    // Truncate if too long (e.g., first 3 sets)
    const displayString = setStrings.slice(0, 3).join(', ') + (setStrings.length > 3 ? '...' : '');

    return displayString;
  };

  const handleAddSet = (session: WorkoutSession) => {
    const currentSetIndex = session.sets.length;
    const lastSession = getLastSession(session.exerciseId);

    let initialWeight = 0;
    let initialReps = 0;

    if (currentSetIndex === 0) {
      // Case 1: First set of the day.
      // Suggest the first set from the last session if available.
      if (lastSession && lastSession.sets.length > 0) {
        initialWeight = lastSession.sets[0].weight;
        initialReps = lastSession.sets[0].reps;
      }
    } else {
      // Case 2: Subsequent sets.
      const prevSetCurrent = session.sets[currentSetIndex - 1];
      let followedHistory = false;

      // Check if user followed the history in the previous set
      if (lastSession && lastSession.sets.length > currentSetIndex - 1) {
        const prevSetHistory = lastSession.sets[currentSetIndex - 1];
        if (prevSetHistory && 
            prevSetCurrent.weight === prevSetHistory.weight && 
            prevSetCurrent.reps === prevSetHistory.reps) {
          followedHistory = true;
        }
      }

      // If user is following history (values matched), suggest the next set from history
      if (followedHistory && lastSession && lastSession.sets[currentSetIndex]) {
        initialWeight = lastSession.sets[currentSetIndex].weight;
        initialReps = lastSession.sets[currentSetIndex].reps;
      } else {
        // Otherwise, standard behavior: copy the values from the previous set in current session
        initialWeight = prevSetCurrent.weight;
        initialReps = prevSetCurrent.reps;
      }
    }

    const newSet: WorkoutSet = {
      id: Date.now().toString() + Math.random(),
      weight: initialWeight,
      reps: initialReps,
      completed: true,
    };
    onUpdateSet(session.id, [...session.sets, newSet]);
  };

  const handleUpdateSetData = (session: WorkoutSession, setId: string, field: 'weight' | 'reps', value: number) => {
    const updatedSets = session.sets.map(set => 
      set.id === setId ? { ...set, [field]: value } : set
    );
    onUpdateSet(session.id, updatedSets);
  };

  const removeSet = (session: WorkoutSession, setId: string) => {
    const updatedSets = session.sets.filter(set => set.id !== setId);
    onUpdateSet(session.id, updatedSets);
  };

  const handleCreateExercise = () => {
    if (newExerciseName.trim()) {
      onAddExercise(newExerciseName);
      setNewExerciseName('');
      setIsAddingExercise(false);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Today's Log Card */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100 min-h-[400px]">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-slate-400 font-bold text-sm tracking-wider uppercase">Today's Workout</h2>
          <span className="text-xs font-medium px-3 py-1 bg-slate-100 text-slate-500 rounded-full">
            {todaysSessions.length} Exercises
          </span>
        </div>

        {todaysSessions.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-center space-y-4">
            <div className="w-16 h-16 bg-primary-50 rounded-full flex items-center justify-center text-primary-400">
              <Plus size={32} />
            </div>
            <p className="text-slate-400">No magic added for this date yet ✨</p>
          </div>
        ) : (
          <div className="space-y-8">
            {todaysSessions.map(session => {
              const exercise = exercises.find(e => e.id === session.exerciseId);
              const prevSummary = getPreviousSessionSummary(session.exerciseId);

              return (
                <div key={session.id} className="animate-fade-in">
                  <div className="flex justify-between items-start mb-3">
                    <div>
                      <h3 className="text-lg font-bold text-slate-800">{exercise?.name}</h3>
                      {prevSummary && (
                        <div className="flex items-center gap-1.5 mt-1 text-xs text-slate-400 font-medium">
                          <History size={12} className="opacity-70" />
                          <span>Last: {prevSummary}</span>
                        </div>
                      )}
                    </div>
                    <button 
                      onClick={() => onDeleteSession(session.id)}
                      className="text-slate-300 hover:text-red-400 transition-colors pt-1"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>

                  <div className="space-y-2">
                    {/* Header Row */}
                    <div className="grid grid-cols-12 gap-2 text-xs font-semibold text-slate-400 mb-2 px-2">
                      <div className="col-span-2 text-center">SET</div>
                      <div className="col-span-4 text-center">KG</div>
                      <div className="col-span-4 text-center">REPS</div>
                      <div className="col-span-2 text-center"></div>
                    </div>

                    {session.sets.map((set, idx) => (
                      <div key={set.id} className="grid grid-cols-12 gap-2 items-center p-2 rounded-xl bg-slate-50 transition-all hover:bg-slate-100">
                        <div className="col-span-2 text-center font-bold text-slate-400">{idx + 1}</div>
                        <div className="col-span-4">
                          <input 
                            type="number" 
                            value={set.weight || ''} 
                            onChange={(e) => handleUpdateSetData(session, set.id, 'weight', Number(e.target.value))}
                            className="w-full text-center bg-white rounded-lg py-2 text-slate-800 font-bold text-lg focus:ring-2 focus:ring-primary-200 outline-none shadow-sm"
                            placeholder="0"
                          />
                        </div>
                        <div className="col-span-4">
                          <input 
                            type="number" 
                            value={set.reps || ''} 
                            onChange={(e) => handleUpdateSetData(session, set.id, 'reps', Number(e.target.value))}
                            className="w-full text-center bg-white rounded-lg py-2 text-slate-800 font-bold text-lg focus:ring-2 focus:ring-primary-200 outline-none shadow-sm"
                            placeholder="0"
                          />
                        </div>
                        <div className="col-span-2 flex justify-center">
                           <button 
                            onClick={() => removeSet(session, set.id)}
                            className="p-2 text-slate-300 hover:text-red-400 transition-colors"
                           >
                             <X size={16} />
                           </button>
                        </div>
                      </div>
                    ))}
                  </div>

                  <button 
                    onClick={() => handleAddSet(session)}
                    className="w-full mt-3 py-2 text-sm font-semibold text-primary-600 bg-primary-50 rounded-xl hover:bg-primary-100 transition-colors flex items-center justify-center gap-2"
                  >
                    <Plus size={16} /> Add Set
                  </button>
                </div>
              );
            })}
          </div>
        )}

        {/* Add Exercise Section */}
        <div className="mt-8 pt-6 border-t border-slate-100">
           {!isAddingExercise ? (
             <div className="flex gap-2">
                <select 
                  className="flex-1 bg-slate-50 text-slate-600 py-3 px-4 rounded-xl outline-none border border-transparent focus:border-primary-300 transition-all appearance-none cursor-pointer"
                  value={selectedExerciseId}
                  onChange={(e) => setSelectedExerciseId(e.target.value)}
                >
                  <option value="" disabled>Select an exercise...</option>
                  {sortedExercises.map(ex => (
                    <option key={ex.id} value={ex.id}>{ex.name}</option>
                  ))}
                </select>
                <button 
                  disabled={!selectedExerciseId}
                  onClick={() => {
                    if (selectedExerciseId) {
                      onAddSession(selectedExerciseId);
                      setSelectedExerciseId('');
                    }
                  }}
                  className="bg-slate-900 text-white rounded-xl w-14 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors shadow-lg shadow-slate-200"
                >
                  <Plus size={24} />
                </button>
             </div>
           ) : (
             <div className="flex gap-2">
               <input 
                 autoFocus
                 type="text" 
                 placeholder="New exercise name..."
                 className="flex-1 bg-white border border-slate-200 text-slate-800 py-3 px-4 rounded-xl outline-none focus:ring-2 focus:ring-primary-200"
                 value={newExerciseName}
                 onChange={(e) => setNewExerciseName(e.target.value)}
               />
               <button 
                 onClick={handleCreateExercise}
                 className="bg-primary-600 text-white rounded-xl px-4 font-semibold text-sm"
               >
                 Save
               </button>
               <button 
                 onClick={() => setIsAddingExercise(false)}
                 className="text-slate-400 px-2"
               >
                 Cancel
               </button>
             </div>
           )}

           {!isAddingExercise && (
             <button 
               onClick={() => setIsAddingExercise(true)}
               className="mt-3 text-xs font-semibold text-primary-500 hover:text-primary-600 block mx-auto"
             >
               + Create new exercise
             </button>
           )}
        </div>
      </div>
    </div>
  );
};
